/* Outfit items carry tiers: C casual, U cute, S sexy, L lewd (default all four).
   The base tiers are set here; Policy may remove some. */
function itemTiers(field,o){return Policy.tiers(o,o.t||"CUSL")}

/* Builds the prompt with Policy's view applied, then adds Policy's notices. */
function compose(){
  const r=Policy.view(composeRaw);
  Policy.notices().forEach(n=>r.checks.push(n));
  r.blocked=!Policy.explicitAllowed();
  r.banner=Policy.banner();
  return r;
}


